#!/usr/bin/env python3
"""Build the public explainer directory from reviewed catalog metadata."""
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
items = json.loads((ROOT / 'catalog.json').read_text())
esc = html.escape
categories = list(dict.fromkeys(item['category'] for item in items))
rows = []
for n, item in enumerate(items, 1):
    secondary = item.get('secondary')
    extra = f'<a class="secondary" href="{esc(secondary["href"])}">{esc(secondary["label"])} ↗</a>' if secondary else ''
    note = f'<span class="note">{esc(item["note"])}</span>' if item.get('note') else ''
    search = ' '.join(str(item.get(k, '')) for k in ('title', 'slug', 'category', 'description', 'format')).lower()
    rows.append(f'''<li data-search="{esc(search)}" data-category="{esc(item['category'])}" data-title="{esc(item['title'].lower())}" data-order="{n}">
      <span class="number" aria-hidden="true">{n:02}</span><div class="entry"><span class="category">{esc(item['category'])}</span>
      <h2><a href="{esc(item['slug'])}/">{esc(item['title'])}<span aria-hidden="true"> ↗</span></a></h2>
      <p>{esc(item['description'])}</p>{note}{extra}</div><span class="format">{esc(item['format'])}</span></li>''')
filters = '<button class="filter" data-category="" aria-pressed="true">Everything <span>'+str(len(items))+'</span></button>'
for category in categories:
    count = sum(item['category'] == category for item in items)
    filters += f'<button class="filter" data-category="{esc(category)}" aria-pressed="false">{esc(category)} <span>{count}</span></button>'
page = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; img-src data:; media-src data:; font-src data:; connect-src 'none'; frame-src 'none'; object-src 'none'; base-uri 'none'; form-action 'none'">
<meta name="description" content="All of Felix Chen’s interactive explainers in one place. Explore 3D visualizations, playable stories and visual guides to engineering, AI, science, history and more."><link rel="canonical" href="https://felixchenyijun.github.io/explainers/"><meta name="theme-color" content="#121917"><title>Explainers — Felix Chen’s interactive directory</title>
<style>
:root{color-scheme:dark;--bg:#121917;--fg:#ecece3;--muted:#a5b2a8;--line:#ffffff1c;--accent:#c4d3ad;--mono:ui-monospace,SFMono-Regular,Menlo,monospace}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:16px/1.55 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}main{max-width:1100px;margin:auto;padding:43px 34px 60px}a{color:inherit;text-underline-offset:4px}button,input,select{font:inherit}button{cursor:pointer}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid #e8bb7d;outline-offset:5px}.topline{display:flex;align-items:center;justify-content:space-between;gap:20px;font:11px var(--mono);letter-spacing:.10em;color:#a9b9ab}.topline a{letter-spacing:0;text-decoration:none;color:var(--muted)}.topline a:hover{color:var(--fg)}.intro-block{display:flex;align-items:flex-end;justify-content:space-between;gap:30px;margin:52px 0 32px}h1{margin:0 0 16px;font:normal 65px/.98 Georgia,"Times New Roman",serif;letter-spacing:-.045em}.intro{max-width:590px;color:var(--muted);margin:0;font-size:16px;line-height:1.7}.total{font:12px/1.8 var(--mono);text-align:right;white-space:nowrap;color:var(--muted);padding-bottom:3px}.total strong{display:block;font:normal 48px/1.15 Georgia,serif;letter-spacing:-.04em;color:var(--accent)}.filters{display:flex;flex-wrap:wrap;gap:7px;margin-bottom:27px}.filter{border:1px solid var(--line);border-radius:4px;padding:7px 10px;background:none;color:#b0bdb3;font-size:11px;line-height:1.3}.filter span{font:9px var(--mono);opacity:.65;margin-left:6px}.filter[aria-pressed=true] span{opacity:1}.filter:hover{border-color:#76917d;color:var(--fg)}.filter[aria-pressed=true]{color:#16221a;background:var(--accent);border-color:var(--accent)}.tools{display:flex;align-items:center;gap:18px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:16px 0}.search{display:flex;align-items:center;gap:10px;flex:1;max-width:450px}.search svg{width:17px;height:17px;flex-shrink:0;stroke:#a4b5a8;fill:none;stroke-width:1.6}input{min-width:0;width:100%;border:1px solid #405247;border-radius:4px;background:#1a2520;color:var(--fg);padding:9px 11px;font-size:13px}input::placeholder{color:#9eafa2}.result-count{font:10px var(--mono);color:#a3b4a7;margin-left:auto;white-space:nowrap}.sort{display:flex;align-items:center;gap:8px}.sort label{font:10px var(--mono);color:#a3b4a7}select{font-size:11px;background:var(--bg);color:var(--fg);border:1px solid #415248;border-radius:4px;padding:7px 8px;max-width:115px}ol{list-style:none;margin:0;padding:0}li{display:grid;grid-template-columns:32px 1fr 163px;gap:18px;padding:27px 0;border-bottom:1px solid var(--line)}[hidden]{display:none!important}.number{padding-top:3px;color:#7f9485;font:11px var(--mono)}.category{color:var(--accent);font:10px var(--mono);text-transform:uppercase;letter-spacing:.08em;display:block;margin-bottom:8px}h2{font-size:23px;font-weight:530;letter-spacing:-.025em;line-height:1.3;margin:0 0 8px}h2 a{text-decoration:none}h2 a span{font-size:16px;color:#7f9886;display:inline-block;transition:transform .15s}h2 a:hover{color:var(--accent)}h2 a:hover span{transform:translate(2px,-2px)}.entry p{max-width:690px;margin:0;color:var(--muted);font-size:14px;line-height:1.7}.format{font:10px/1.7 var(--mono);color:#9aac9e;padding-top:24px;text-align:right}.note,.secondary{display:block;margin-top:9px;font-size:11px;color:#92a698}.secondary{color:var(--accent);width:fit-content}#empty{padding:40px 0;border-bottom:1px solid var(--line);color:var(--muted);font-size:14px}#empty strong{display:block;color:var(--fg);font-size:20px;font-weight:500;margin-bottom:8px}#clear{display:block;margin-top:17px;border:1px solid #637b68;background:none;color:var(--accent);border-radius:4px;padding:8px 13px;font-size:12px}footer{display:flex;justify-content:space-between;gap:20px;margin-top:29px;color:#96a79b;font-size:11px}footer p{margin:0;max-width:720px}footer a{white-space:nowrap}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}
@media(max-width:640px){main{padding:25px 21px 40px}.topline{font-size:9px;letter-spacing:.07em}.intro-block{margin-top:39px;gap:18px}h1{font-size:48px;margin-bottom:16px}.intro{font-size:14px}.total{display:none}.filters{gap:6px;margin-bottom:23px}.filter{font-size:10px;padding:7px 8px}.filter span{font-size:8px;margin-left:3px}.tools{gap:10px;flex-wrap:wrap;padding:14px 0}.search{max-width:none;flex-basis:100%;gap:9px}.result-count{margin-left:25px}.sort{margin-left:auto}.sort label{font-size:9px}select{font-size:10px;padding:5px 7px}li{grid-template-columns:23px 1fr;gap:10px;padding:24px 0}.format{grid-column:2;text-align:left;padding:0;margin-top:-1px;font-size:10px}h2{font-size:21px}.entry p{font-size:13px}.category{font-size:9px}.number{font-size:10px}footer{flex-direction:column;gap:14px}}
@media(prefers-reduced-motion:reduce){*{transition:none!important}}
</style></head><body><main id="top"><div class="topline"><span>FELIX CHEN / THE EXPLAINER COLLECTION</span><a href="https://github.com/felixchenyijun/explainers">Source ↗</a></div>
<div class="intro-block"><div><h1>Explainers.</h1><p class="intro">A directory of everything I’ve made to understand how things work. Turn a model, change a rule, follow an idea.</p></div><div class="total"><strong>__COUNT__</strong>interactive explainers</div></div>
<div class="filters" role="group" aria-label="Filter by topic">__FILTERS__</div>
<div class="tools"><div class="search"><svg viewBox="0 0 20 20" aria-hidden="true"><circle cx="8" cy="8" r="5.5"/><path d="m12 12 5 5"/></svg><label for="search" class="sr-only">Search all explainers</label><input id="search" type="search" placeholder="Search a title, topic or question…" autocomplete="off"></div><span id="count" class="result-count" aria-live="polite">__COUNT__ of __COUNT__ explainers</span><div class="sort"><label for="sort">SORT</label><select id="sort"><option value="curated">Collection order</option><option value="az">Title A–Z</option></select></div></div>
<ol id="entries">__ROWS__</ol><div id="empty" hidden><strong>No explainers found.</strong>Try a broader search or switch topics.<button id="clear">Clear search &amp; filters</button></div>
<footer><p>These are educational models and visual explanations. Sources, assumptions and research dates are included inside each explainer.</p><a href="#top">Back to top ↑</a></footer></main>
<script>
const search=document.querySelector('#search'),rows=[...document.querySelectorAll('#entries li')],count=document.querySelector('#count'),empty=document.querySelector('#empty'),filters=[...document.querySelectorAll('.filter')];let category='';
function update(){const terms=search.value.trim().toLowerCase().split(/\\s+/).filter(Boolean);let n=0;for(const row of rows){const match=(!category||row.dataset.category===category)&&terms.every(term=>row.dataset.search.includes(term));row.hidden=!match;n+=match?1:0}count.textContent=n+' of '+rows.length+' explainers';empty.hidden=n!==0;for(const button of filters)button.setAttribute('aria-pressed',button.dataset.category===category)}
search.addEventListener('input',update);for(const button of filters)button.addEventListener('click',()=>{category=button.dataset.category;update()});document.querySelector('#clear').addEventListener('click',()=>{search.value='';category='';update();search.focus()});document.querySelector('#sort').addEventListener('change',e=>{const sorted=rows.slice().sort((a,b)=>e.target.value==='az'?a.dataset.title.localeCompare(b.dataset.title):Number(a.dataset.order)-Number(b.dataset.order));document.querySelector('#entries').append(...sorted)});
</script></body></html>'''
page=page.replace('__COUNT__',str(len(items))).replace('__FILTERS__',filters).replace('__ROWS__','\n'.join(rows))
(ROOT/'docs'/'index.html').write_text(page)
print(f'Built explainer directory: {len(items)} entries across {len(categories)} topics.')
